def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    op_d = 0
    my_c = 0
    my_d = 0
    for i in range(n):
        if op[i] == 'C':
            op_c += 1
        else:
            op_d += 1
        if my[i] == 'C':
            my_c += 1
        else:
            my_d += 1

    last_my = my[-1]
    last_op = op[-1]

    # Consecutive run lengths at the end
    consec_op_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            consec_op_d += 1
        else:
            break
    consec_op_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            consec_op_c += 1
        else:
            break

    # Recent windows
    w = 6 if n >= 6 else n
    recent_op_c = 0
    for i in range(n - w, n):
        if op[i] == 'C':
            recent_op_c += 1
    w10 = 10 if n >= 10 else n
    recent10_op_c = 0
    for i in range(n - w10, n):
        if op[i] == 'C':
            recent10_op_c += 1

    op_rate = op_c / float(n)

    # Very early: cooperative opening
    if n < 4:
        return 'C'

    # Always-defector detection: punish hard, probe rarely
    if op_d == n:
        if n % 17 == 0:
            return 'C'
        return 'D'

    # Zero-defection opponent: keep cooperating, take endgame profit
    if op_d == 0:
        if n >= 96:
            return 'D'
        if n >= 80 and n % 3 == 0:
            return 'D'
        return 'C'

    # Opponent mostly cooperative: stay with cooperation, defect near end
    if op_rate >= 0.85:
        if n >= 95:
            return 'D'
        if n >= 85 and n % 2 == 0:
            return 'D'
        if last_op == 'C':
            return 'C'
        # occasional single defection: forgive quickly
        if consec_op_d >= 2:
            return 'D'
        return 'C'

    # Opponent mostly defecting: defect, rare probe
    if op_rate <= 0.2:
        if n % 13 == 0 and last_op == 'D' and consec_op_d >= 2:
            return 'C'
        return 'D'

    remaining = 100 - n

    # Endgame: exploit cooperators hard
    if remaining <= 3:
        if op_rate >= 0.5:
            return 'D'
        if last_op == 'C':
            return 'D'
        return 'D'

    if remaining <= 8:
        if op_rate >= 0.55 or consec_op_c >= 2:
            return 'D'
        if last_op == 'D':
            return 'D'
        if op_rate <= 0.3:
            return 'D'
        return 'C'

    # If opponent just defected: punish, but forgive if they're mostly cooperative
    if last_op == 'D':
        # Isolated defection against a cooperative opponent
        if op_rate >= 0.6 and consec_op_d == 1:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        if consec_op_d >= 3:
            # Long defection streak; probe occasionally
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if op_rate >= 0.45:
            return 'D'
        return 'D'

    # Opponent cooperated last round
    # If we defected last and they still cooperated, calm down to rebuild
    if last_my == 'D':
        if op_rate >= 0.5:
            return 'C'
        if consec_op_c >= 2:
            return 'C'
        return 'C'

    # Opponent cooperated, we cooperated: consider probing a highly cooperative foe
    if op_rate >= 0.7 and recent10_op_c >= 8:
        # risky probe: only if we haven't defected recently
        if my_d == 0 and n >= 20 and n % 9 == 0:
            return 'D'
        return 'C'

    # Moderate opponent: tit-for-tat with retaliation and quick forgiveness
    if op_rate >= 0.4:
        return 'C'

    # Opponent leans defection-heavy: defect
    return 'D'
